import React from 'react';
import { View, Text, FlatList, Image, TouchableOpacity, StyleSheet, Dimensions } from 'react-native';

const { width } = Dimensions.get('window');
const COLUMN_WIDTH = width / 2 - 15;

interface ProductListProps {
  data: any[];
  onPress: (item: any) => void;
}

const ProductList: React.FC<ProductListProps> = ({ data, onPress }) => {
  const renderItem = ({ item }: { item: any }) => {
    const imageUrl = item.image || (item.images && item.images[0]?.url) || 'https://via.placeholder.com/300';
    
    return (
      <TouchableOpacity 
        style={styles.card} 
        onPress={() => onPress(item)}
        activeOpacity={0.9}
      >
        <Image source={{ uri: imageUrl }} style={styles.image} resizeMode="cover" />
        <View style={styles.details}>
          <Text style={styles.name} numberOfLines={2}>{item.name}</Text>
          <View style={styles.priceRow}>
            <Text style={styles.price}>₹{item.price}</Text>
            {item.oldPrice && <Text style={styles.oldPrice}>₹{item.oldPrice}</Text>}
          </View>
          <TouchableOpacity style={styles.addButton}>
            <Text style={styles.addButtonText}>ADD +</Text>
          </TouchableOpacity>
        </View>
      </TouchableOpacity>
    );
  };

  return (
    <View style={styles.container}>
      <FlatList
        data={data}
        renderItem={renderItem}
        keyExtractor={(item) => item.id.toString()}
        numColumns={2}
        columnWrapperStyle={styles.row}
        scrollEnabled={false} // Since we put this inside a parent ScrollView usually
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    paddingHorizontal: 10,
  },
  row: {
    justifyContent: 'space-between',
  },
  card: {
    width: COLUMN_WIDTH,
    backgroundColor: '#fff',
    marginBottom: 10,
    borderRadius: 8,
    overflow: 'hidden',
    borderWidth: 1,
    borderColor: '#eee',
    // Shadow
    shadowColor: "#000",
    shadowOffset: {
      width: 0,
      height: 1,
    },
    shadowOpacity: 0.1,
    shadowRadius: 2.22,
    elevation: 2,
  },
  image: {
    height: COLUMN_WIDTH, // Square image
    width: '100%',
  },
  details: {
    padding: 10,
  },
  name: {
    fontSize: 14,
    color: '#333',
    marginBottom: 5,
    height: 36, // fixed height for 2 lines
  },
  priceRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 8,
  },
  price: {
    fontSize: 14,
    fontWeight: 'bold',
    color: '#000',
  },
  oldPrice: {
    fontSize: 12,
    color: '#999',
    textDecorationLine: 'line-through',
    marginLeft: 5,
  },
  addButton: {
    borderWidth: 1,
    borderColor: '#007AFF',
    borderRadius: 4,
    paddingVertical: 5,
    alignItems: 'center',
    justifyContent: 'center',
  },
  addButtonText: {
    color: '#007AFF',
    fontSize: 12,
    fontWeight: 'bold',
  },
});

export default ProductList;
